#!/bin/bash
# Generated By: Claude Code (claude-opus-5-5)
#
# Self-check for `sandbox.sh --rename NEW`: run from inside ~/sandboxes/<old>/,
# it asks, moves the directory, rewrites .name and tasks.json, marks
# recreate_pending, then recreates under NEW. The container keeps its
# sb-<hash>, which only works because --create takes the openshell name from the
# manifest instead of hashing the new name.
#
# openshell and podman are isolate.sh's fail-closed fakes, so the recreate the
# rename hands off to fails — which is the case recreate_pending exists for.
#
# Run: tests/test-rename.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
# Creates mint an openshell name, which asks the gateway what is taken.
fake_openshell_list
trap 'rm -rf "$TMP"' EXIT

fail() { echo "FAIL: $1" >&2; exit 1; }

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
    > "${WORK}/config/site.env"
SANDBOX_SH="${WORK}/scripts/sandbox.sh"

FAKE_HOME="${TMP}/home"
SB="${FAKE_HOME}/sandboxes"
OLD="${SB}/old"

reset() {
    rm -rf "$SB"
    mkdir -p "$OLD"
    printf '{"name":"old","openshell_name":"sb-kept","profile":"personal","repos":{}}' \
        > "${OLD}/manifest.json"
}
# rename_in DIR ANSWER ARGS...: run --rename from DIR with ANSWER on stdin.
rename_in() {
    local dir="$1" answer="$2"
    shift 2
    (cd "$dir" && HOME="$FAKE_HOME" bash "$SANDBOX_SH" --rename "$@" <<<"$answer" 2>&1)
}

# --- declining changes nothing ---
reset
out="$(rename_in "$OLD" n new)" || fail "declined rename exited non-zero: ${out}"
grep -qF "recreates the sandbox" <<<"$out" || fail "prompt did not say a recreate follows"
[[ -d "$OLD" && ! -e "${SB}/new" ]] || fail "declined rename moved the directory"
[[ "$(jq -r '.recreate_pending // false' "${OLD}/manifest.json")" == false ]] \
    || fail "declined rename marked recreate_pending"

# EOF is a no too.
reset
rename_in "$OLD" "" new </dev/null >/dev/null || fail "rename on EOF exited non-zero"
[[ -d "$OLD" ]] || fail "rename on EOF moved the directory"

# --- refusals before the prompt ---
reset
mkdir -p "${SB}/taken"
rename_in "$OLD" y taken >/dev/null && fail "rename onto an existing directory succeeded"
[[ -d "$OLD" ]] || fail "refused rename moved the directory"

reset
rename_in "$OLD" y "bad/name" >/dev/null && fail "rename accepted a name with a slash"
rename_in "$OLD" y ".hidden" >/dev/null && fail "rename accepted a leading dot"
rename_in "$TMP" y new >/dev/null && fail "rename ran outside ~/sandboxes/<name>/"
[[ -d "$OLD" ]] || fail "refused rename moved the directory"

# --- --dryrun prints the move and the recreate, writes nothing ---
reset
out="$(rename_in "$OLD" y new --dryrun)" || fail "dryrun rename failed: ${out}"
grep -qF "[dryrun]: mv ${OLD} ${SB}/new" <<<"$out" || fail "dryrun did not print the move"
grep -qF -- "--recreate new --profile personal" <<<"$out" || fail "dryrun did not print the recreate"
[[ -d "$OLD" && ! -e "${SB}/new" ]] || fail "dryrun moved the directory"

# --- confirmed: moved, renamed, pending, tasks.json, recreate attempted ---
reset
out="$(rename_in "$OLD" y new --no-connect || true)"
NEWM="${SB}/new/manifest.json"
[[ ! -e "$OLD" && -f "$NEWM" ]] || fail "confirmed rename did not move the directory: ${out}"
[[ "$(jq -r .name "$NEWM")" == new ]] || fail ".name not rewritten"
[[ "$(jq -r .openshell_name "$NEWM")" == sb-kept ]] || fail ".openshell_name changed"
[[ "$(jq -r .profile "$NEWM")" == personal ]] || fail "rename lost .profile"
# The fakes make the recreate fail, so the flag must still be there for the
# next --connect/--ensure.
[[ "$(jq -r '.recreate_pending // false' "$NEWM")" == true ]] \
    || fail "recreate_pending not left for the next connect"
grep -qF -- "--ensure new --profile personal" "${SB}/new/.vscode/tasks.json" \
    || fail "tasks.json still ensures the old name"
grep -qF "Recreating sandbox new" <<<"$out" || fail "rename did not hand off to --recreate: ${out}"

# --- --create names the container from the manifest, not a fresh hash ---
out="$(HOME="$FAKE_HOME" bash "$SANDBOX_SH" --create new --profile personal \
    --no-clone --no-connect --dryrun 2>&1 || true)"
grep -qF "(openshell: sb-kept)" <<<"$out" || fail "--create hashed the new name instead of reusing sb-kept"

# --- reusing the old name: create foo, rename to bar, use foo again ---
# old's container carries the name a name-derived scheme would give "old"
# (md5, as sandboxes made before random names do), and a rename keeps it.
# Nothing addressed as "old" may resolve to that container.
# shellcheck disable=SC1091
source "${WORK}/scripts/lib.sh"
LEGACY="sb-$(printf '%s' old | md5sum | cut -c1-12)"
reset
jq --arg n "$LEGACY" '.openshell_name = $n' "${OLD}/manifest.json" > "${OLD}/m.tmp" \
    && cat "${OLD}/m.tmp" > "${OLD}/manifest.json" && rm "${OLD}/m.tmp"
rename_in "$OLD" y new --no-connect >/dev/null 2>&1 || true
[[ "$(jq -r .openshell_name "${SB}/new/manifest.json")" == "$LEGACY" ]] \
    || fail "rename did not keep the legacy name"

# --create old: a fresh name, and .env carries the same one the container gets.
out="$(HOME="$FAKE_HOME" bash "$SANDBOX_SH" --create old --profile personal \
    --no-clone --no-connect --dryrun 2>&1 || true)"
created="$(sed -n 's/.*(openshell: \(sb-[0-9a-f]*\)).*/\1/p' <<<"$out")"
is_our_openshell_name "$created" || fail "--create old printed no openshell name: ${out}"
[[ "$created" != "$LEGACY" ]] || fail "--create old reused the renamed sandbox's ${LEGACY}"
grep -qF "SANDBOX_OPENSHELL_NAME=${created}" <<<"$out" \
    || fail ".env SANDBOX_OPENSHELL_NAME does not match the created ${created}"
rm -rf "${SB}/old"

# --delete old, no directory: refuses rather than deleting bar's container.
out="$(HOME="$FAKE_HOME" bash "$SANDBOX_SH" --delete old 2>&1)" \
    && fail "--delete old succeeded with no sandbox named old: ${out}"
grep -qF "old has no manifest" <<<"$out" || fail "--delete old did not say why: ${out}"
grep -qF "openshell blocked: sandbox delete" <<<"$out" \
    && fail "--delete old reached openshell delete: ${out}"

# --ensure old, no directory, while bar's container is live: creates, never
# connects to it.
fake_openshell_list "$LEGACY"
out="$(HOME="$FAKE_HOME" bash "$SANDBOX_SH" --ensure old \
    --profile personal --no-clone --no-connect --dryrun 2>&1 || true)"
grep -qF "exists" <<<"$out" && fail "--ensure old connected to the renamed sandbox: ${out}"
ensured="$(sed -n 's/.*(openshell: \(sb-[0-9a-f]*\)).*/\1/p' <<<"$out")"
[[ -n "$ensured" && "$ensured" != "$LEGACY" ]] \
    || fail "--ensure old did not create under a fresh name: ${out}"

# --- no .openshell_name: nothing to rename, nothing to delete ---
reset
jq 'del(.openshell_name)' "${OLD}/manifest.json" > "${OLD}/m.tmp" \
    && cat "${OLD}/m.tmp" > "${OLD}/manifest.json" && rm "${OLD}/m.tmp"
out="$(rename_in "$OLD" y new --no-connect)" \
    && fail "rename of a manifest with no .openshell_name succeeded: ${out}"
grep -qF "has no .openshell_name" <<<"$out" || fail "rename refusal did not say why: ${out}"
[[ -d "$OLD" && ! -e "${SB}/new" ]] || fail "refused rename moved the directory"
out="$(HOME="$FAKE_HOME" bash "$SANDBOX_SH" --delete old 2>&1)" \
    && fail "--delete of a manifest with no .openshell_name succeeded: ${out}"
grep -qF "openshell blocked: sandbox delete" <<<"$out" \
    && fail "--delete with no .openshell_name reached openshell delete: ${out}"
[[ -d "$OLD" ]] || fail "--delete with no .openshell_name removed the directory"

echo "PASS: tests/test-rename.sh"
